def git_tool(op: str, message: str = "") -> str:
    cmds = {
        "status": ["git", "status", "--short"],
        "diff": ["git", "diff", "--stat"],
        "commit": ["git", "commit", "-am", message[:200]],
        "push": ["git", "push", "origin", f"HEAD:{AGENT_BRANCH}"],
    }
    if op not in cmds or (op == "commit" and not message.strip()):
        return "refused"
    p = subprocess.run(cmds[op], cwd=REPO_DIR, capture_output=True, text=True, timeout=60)
    return (p.stdout + p.stderr)[-2000:]

