SCRATCH = Path("/tmp/agent-scratch").resolve()
MAX_FILES = 200

def cleanup_scratch(subdir: str, dry_run: bool = True) -> list[str]:
    target = (SCRATCH / subdir).resolve()
    if not target.is_relative_to(SCRATCH) or target == SCRATCH:
        raise ValueError("outside scratch area")
    files = [p for p in target.rglob("*") if p.is_file()]
    if len(files) > MAX_FILES:
        raise ValueError("too many files; ask the user")
    if not dry_run:
        for p in files:
            p.unlink()
    return [str(p) for p in files]

def accept_delegation(token: str, seen_jti: set) -> dict:
    claims = jwt.decode(token, ORCHESTRATOR_PUBLIC_KEY, algorithms=["ES256"],
                        audience="worker-agent", issuer="orchestrator-agent",
                        options={"require": ["exp", "iat", "jti"]})
    if claims["jti"] in seen_jti:
        raise PermissionError("replayed delegation")
    seen_jti.add(claims["jti"])
    if claims["task"] not in WORKER_TASKS:
        raise ValueError(claims["task"])
    return claims

