def agent_loop(client, user_goal: str, tools: list) -> str:
    messages = [{"role": "user", "content": user_goal}]
    for _ in range(MAX_STEPS):
        resp = client.messages.create(model=MODEL, max_tokens=1024, system=AGENT_PROMPT,
                                      tools=tools, messages=messages)
        if resp.stop_reason != "tool_use":
            return resp.content[0].text
        messages.append({"role": "assistant", "content": resp.content})
        results = [{"type": "tool_result", "tool_use_id": b.id,
                    "content": str(ALLOWED_TOOLS[b.name](**b.input)) if b.name in ALLOWED_TOOLS else "unknown tool"}
                   for b in resp.content if b.type == "tool_use"]
        messages.append({"role": "user", "content": results})
    return "step limit reached"

